terraform_vars_snippet:
variable "orchestrator" {
  type = string
  description = "Select 'asg' or 'karpenter'"
  default = "karpenter"
}

variable "gpu_instance_types" {
  type = list(string)
  default = ["p4d.24xlarge"]
  description = "Preferred GPU instance families for the pool"
}

output "nodepool_name" {
  value = local.nodepool_name
  description = "Canonical nodepool name used for tagging and Console"
}

# Example usage will be provided in examples/asg and examples/karpenter directories
